sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    c.ratingText = "";

    c.loading = false;

    c.successMessage = "";

    c.errorMessage = "";


    c.selectRating = function(rating) {

        c.data.rating = rating;


        if (rating == 1) {

            c.ratingText = "Very Poor";

        } else if (rating == 2) {

            c.ratingText = "Poor";

        } else if (rating == 3) {

            c.ratingText = "Average";

        } else if (rating == 4) {

            c.ratingText = "Good";

        } else {

            c.ratingText = "Excellent";

        }

    };


    c.submitFeedback = function() {

        c.successMessage = "";

        c.errorMessage = "";


        if (!c.data.rating) {

            c.errorMessage =
                "Please select a star rating.";

            return;
        }


        if (!c.data.comment) {

            c.errorMessage =
                "Please enter your feedback.";

            return;
        }


        c.loading = true;


        c.server.get({

            action: "submit_feedback",

            rating: c.data.rating,

            comment: c.data.comment

        }).then(function(response) {

            c.loading = false;


            if (response.data.success) {

                c.successMessage =
                    response.data.message;


                c.data.rating = 0;

                c.data.comment = "";

                c.ratingText = "";

            } else {

                c.errorMessage =
                    response.data.message;

            }

        });

    };


    c.goBack = function() {

        window.location.href =
            "?id=student_welcome";

    };

};

sp_widget.css:
.feedback-page {
    min-height: 100vh;

    background: #f3f6fa;

    padding: 35px;

    font-family: "Segoe UI", Arial, sans-serif;

    color: #102235;
}


.feedback-header {
    background: white;

    border: 1px solid #dce4eb;

    border-radius: 16px;

    padding: 25px 30px;

    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 25px;
}


.feedback-header h1 {
    margin: 0 0 7px;

    font-size: 29px;
}


.feedback-header p {
    margin: 0;

    color: #63768a;
}


.back-btn {
    background: white;

    border: 1px solid #ccd7e0;

    padding: 10px 18px;

    border-radius: 8px;

    cursor: pointer;
}


.feedback-card {
    background: white;

    max-width: 750px;

    margin: auto;

    padding: 40px;

    border-radius: 18px;

    border: 1px solid #dce4eb;

    text-align: center;
}


.feedback-card h2 {
    margin: 0;

    font-size: 26px;
}


.feedback-subtitle {
    color: #718397;

    margin-top: 8px;

    margin-bottom: 25px;
}


/* STARS */

.stars {
    display: flex;

    justify-content: center;

    gap: 10px;

    margin: 20px 0 10px;
}


.star {
    font-size: 45px;

    color: #d5dce2;

    cursor: pointer;

    transition: .15s;
}


.star:hover {
    transform: scale(1.15);
}


.star.selected {
    color: #f4b400;
}


.rating-text {
    height: 25px;

    color: #66798d;

    font-weight: 600;

    margin-bottom: 25px;
}


.form-group {
    text-align: left;

    margin-bottom: 22px;
}


.form-group label {
    display: block;

    font-weight: 700;

    margin-bottom: 9px;
}


.feedback-input {
    width: 100%;

    box-sizing: border-box;

    border: 1px solid #ccd7e0;

    border-radius: 9px;

    padding: 14px;

    font-size: 15px;

    resize: vertical;

    outline: none;
}


.feedback-input:focus {
    border-color: #117f75;

    box-shadow:
        0 0 0 3px rgba(17,127,117,.10);
}


.submit-feedback {
    width: 100%;

    height: 52px;

    border: none;

    border-radius: 9px;

    background: #117f75;

    color: white;

    font-size: 17px;

    font-weight: 700;

    cursor: pointer;
}


.submit-feedback:hover {
    background: #096b62;
}


.submit-feedback:disabled {
    opacity: .6;
}


.success-message {
    margin-top: 20px;

    padding: 14px;

    border-radius: 8px;

    background: #e7f7ee;

    color: #137442;
}


.error-message {
    margin-top: 20px;

    padding: 14px;

    border-radius: 8px;

    background: #fff0f0;

    color: #c62828;
}


@media(max-width:600px) {

    .feedback-page {
        padding: 18px;
    }

    .feedback-header {
        flex-direction: column;

        align-items: flex-start;

        gap: 18px;
    }

    .feedback-card {
        padding: 25px 20px;
    }

    .star {
        font-size: 36px;
    }

}

sp_widget.script:
(function() {

    data.success = false;

    data.message = "";


    if (input &&
        input.action == "submit_feedback") {


        if (!input.rating) {

            data.message =
                "Please select a rating.";

            return;
        }


        if (!input.comment) {

            data.message =
                "Please enter your feedback.";

            return;
        }


        var feedback =
            new GlideRecord("u_cfms_feedback");


        feedback.initialize();


        feedback.u_student =
            gs.getUserID();


        feedback.u_rating =
            input.rating;


        feedback.u_comments =
            input.comment;


        var result =
            feedback.insert();


        if (result) {

            data.success = true;

            data.message =
                "Thank you! Your feedback has been submitted.";

        } else {

            data.message =
                "Unable to submit feedback.";

        }

    }

})();
